    [Serializable]
    public sealed class FlightStoryEnemyProfile
    {
        public string Id, Name, Kind, RewardClass, Notes, Source;
        public int Gauge, Damage, ControlPercent, ExperienceReward;
        public float Period, Speed, Radius, Telegraph;
        public bool IsBoss => Kind == "보스";
        public bool IsNonlethal => RewardClass != "NORMAL";
        // Step4 provisional authoring values: no diagonal angles existed in the approved table.
        public float[] DiagonalYaw = { -15f, 0f, 15f };
        public float[] DiagonalPitch = { -6f, 0f, 6f };
    }

