            new FlightStoryPatternProfile { Id = "BP-RAY-02", BossId = "B-RAY", Name = "양 날개 교대 사격", Phase = 2, Telegraph = 1.5f, Bursts = 3, Count = 7, Interval = 0.7f, Speed = 12f, Damage = 10, ActiveSeconds = 1.6f, RecoverySeconds = 1.6f, Geometry = FlightStoryGeometry.AlternatingFan, GeometryNotes = "저지 내구300→0.\n발사점(-3,4,44)→(3,4,44)→(-3,4,44) 순서다.\n각 날개를 순서대로 점등하며 하나의 고정 조준축을 공유한다.\n수평 조준축을 예고 시작에 고정한다.\n7발 yaw -32~32°, pitch -6/+6° 교차이며 발사 중 추적하지 않는다.\n탄 수명8초·탄 반경0.1이다.\n몸통 피해 배율1.0.", SafeRoute = "전방 z≤12에서 높은 회피 후보 y18~24 또는 조준축 바깥으로 이동한다.\n기체·탄 반경을 뺀 유효 폭4 이상의 연결 경로를 씬에서 검증한다.\n경계·보호 대상과 겹치면 공격을 보류한다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n정예 프로필·ELITE 보상·제어50%다.\n내구0 뒤 살아서 비공격 무리와 분리되는 AI 이탈을 사용한다.\n반복 주기 예약량 검산: 42발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-P-01", BossId = "B-PROLOGUE", Name = "항로 앞 고정 조준 연사", Phase = 1, Telegraph = 1.5f, Bursts = 4, Count = 1, Interval = 0.3f, Speed = 15f, Damage = 10, ActiveSeconds = 1.1f, RecoverySeconds = 1.4f, Geometry = FlightStoryGeometry.Aimed, GeometryNotes = "저지1500→1000.\n발사점(0,4,44)에서 플레이어의 수평 위치를 한 번 조준한다.\n같은 직선으로4발, 재조준·유도 없음.\n탄 수명8초·반경0.1.", SafeRoute = "예고 뒤 조준선 좌우 또는 위아래로 벗어난다.\n조준선에서 기체·탄 반경을 더한 거리 이상 떨어진 유효 폭4의 길을 유지한다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n종명 미확정 대형 마물이다.\n저지 수치는 생물의 사망 판정으로 연결하지 않는다.\n반복 주기 예약량 검산: 8발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-P-02", BossId = "B-PROLOGUE", Name = "중앙 입체 고리", Phase = 2, Telegraph = 1.5f, Bursts = 3, Count = 12, Interval = 0.6f, Speed = 12f, Damage = 15, ActiveSeconds = 1.4f, RecoverySeconds = 1.6f, Geometry = FlightStoryGeometry.Ring, GeometryNotes = "저지1000→500.\n중앙(0,4,44)에서 고정 수평축을 중심으로 cone24°·roll30° 간격의12발 고리를 쏜다.\n세 고리의 중심축은 동일하다.\n탄 수명8초·반경0.1.", SafeRoute = "z≤12의 고정 중심축 안쪽 공간을 회피 후보로 둔다.\n고리 안쪽의 반경4 공간과 진입 경로를 기체·탄 부피로 검사한다.\n상승·하강으로 고리 밖을 지날 때는 도착 시각을 별도로 검증한다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n현재 코드 Ring12의 형태를 참고한 장면 배치다.\n고리 사이 틈의 실제 공정성은 플레이 대기다.\n반복 주기 예약량 검산: 72발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-P-03", BossId = "B-PROLOGUE", Name = "좌우 교차 나선", Phase = 3, Telegraph = 1.5f, Bursts = 3, Count = 8, Interval = 0.65f, Speed = 12f, Damage = 20, ActiveSeconds = 1.5f, RecoverySeconds = 1.8f, Geometry = FlightStoryGeometry.CrossSpiral, GeometryNotes = "저지500→0.\n좌우 발사점(-6,4,44)/(6,4,44)이 중앙 전방14 지점을 향한다.\n각 발사점4갈래, 좌 roll0/26/52°, 우45/19/-7°다.\ncone8°는 기존17°를 좁힌 새 시험값이다.\n탄 수명8초·반경0.1.", SafeRoute = "높은 회피 후보 y18~24에서 좌우 교차점에 접근하지 않는다.\nz≤12의 상승 연결 경로와 유효 폭4를 실제 씬에서 검사한다.\n보호선박 항로와 겹치면 발사를 보류한다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n기존 Spiral4를 좌우에서 사용하지만 cone8°·예고·간격은 신규 설계다.\n마지막 저지 뒤 구조선 안전 도착·전원 확인·의료 인계 전 정산 금지.\n반복 주기 예약량 검산: 48발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-KARDEN-01", BossId = "B-KARDEN", Name = "경고 뒤 직선 돌진", Phase = 1, Telegraph = 1.5f, Bursts = 1, Count = 0, Interval = 0f, Speed = 14f, Damage = 15, ActiveSeconds = 2f, RecoverySeconds = 1.6f, Geometry = FlightStoryGeometry.Charge, GeometryNotes = "압박 저지900→600.\n(0,4,44)에서 예고된 수평 경로를 최대28 이동한다.\n돌진 속도14·반경1이며 도중 추적·회전하지 않는다.\n종점에서 접촉 공격을 끄고 다음 공격 전 시작 위치로 비공격 복귀한다.", SafeRoute = "예고된 돌진 원통의 좌우 또는 위쪽으로 벗어난다.\n주민은 위협 경로에 진입하지 않고 승인 대기 지점에서 기다린다.\n돌진 종점과 후퇴 경로가 양측 안전 동선을 침범하면 발사·이동을 보류한다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n보스 제어0%이며 기본 공격으로 저지 게이지를 줄인다.\n위 speed는 이동 속도이며 탄환은 없다.\nMID 분류와3단계 패턴 수는 독립이다.\n반복 주기 예약량 검산: 0발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-KARDEN-02", BossId = "B-KARDEN", Name = "창고 앞 압박 부채", Phase = 2, Telegraph = 1.5f, Bursts = 3, Count = 7, Interval = 0.65f, Speed = 12f, Damage = 15, ActiveSeconds = 1.5f, RecoverySeconds = 1.6f, Geometry = FlightStoryGeometry.Fan, GeometryNotes = "압박 저지600→300.\n발사점(0,4,44)의 갑주가 빛난 뒤 같은 방향으로 사격한다.\n수평 조준축을 예고 시작에 고정한다.\n7발 yaw -32~32°, pitch -6/+6° 교차이며 발사 중 추적하지 않는다.\n탄 수명8초·탄 반경0.1이다.", SafeRoute = "전방 z≤12에서 높은 회피 후보 y18~24 또는 조준축 바깥으로 이동한다.\n기체·탄 반경을 뺀 유효 폭4 이상의 연결 경로를 씬에서 검증한다.\n경계·보호 대상과 겹치면 공격을 보류한다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\nMID 보상 분류·강제 이동/속박0%다.\n보호 대상의 안전 대기 시간을 실패 제한시간으로 바꾸지 않는다.\n반복 주기 예약량 검산: 42발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-KARDEN-03", BossId = "B-KARDEN", Name = "압박 사격 뒤 짧은 전진", Phase = 3, Telegraph = 1.5f, Bursts = 2, Count = 7, Interval = 0.65f, Speed = 12f, Damage = 15, ActiveSeconds = 3f, RecoverySeconds = 1.8f, Geometry = FlightStoryGeometry.FanCharge, GeometryNotes = "압박 저지300→0.\n예고한 한 축으로7발 부채를2회 쏜다.\n수평 조준축을 예고 시작에 고정한다.\n7발 yaw -32~32°, pitch -6/+6° 교차이며 발사 중 추적하지 않는다.\n탄 수명8초·탄 반경0.1이다.\n첫 발 기준1.1초부터 같은 고정축으로 최대21·속도14의 짧은 돌진을1회 한다.\n사격과 이동 경로를 예고 때 함께 표시한다.", SafeRoute = "높은 y18~24 회피 후보나 예고된 돌진축의 바깥으로 이동한다.\n주민 구간과 후퇴 지점 사이의 유효 폭4를 확보한다.\n돌진을 이용해 카르덴을 장면 경계 밖으로 밀어내는 조건은 없다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n저지0은 C02-S02 압박 중지다.\nS03 낙석 해소·주민과 마물 양측 구조·사격 중지까지 MID 격파 확정을 기다린다.\n반복 주기 예약량 검산: 28발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-VARKAN-01", BossId = "B-VARKAN", Name = "첫 방벽의 두 갈래 씨앗탄", Phase = 1, Telegraph = 1.5f, Bursts = 2, Count = 8, Interval = 1f, Speed = 12f, Damage = 15, ActiveSeconds = 2f, RecoverySeconds = 1.6f, Geometry = FlightStoryGeometry.SplitPair, GeometryNotes = "방벽900→600; 활성 구획(-6,4,44).\n한 버스트는 부모탄2발(속도8)이0.8초 뒤 각각3발(속도12)로 갈라진다.\n부모를 회수한 뒤 자식을 생성한다.\n총8발/버스트이며 자식 yaw -16/0/16°, pitch0°다.\n분열 방향은 부모탄 표면에 미리 표시하고 재조준하지 않는다.", SafeRoute = "분열 전에 부모 진행축 옆이나 위로 이동한다.\ny12~20의 회피 후보와 양측 빈 공역 연결을 검사한다.\n닫힌 방벽 쪽을 유일한 탈출로로 안내하지 않는다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n분열은 현재 기본4종 패턴과 별도 구현이 필요하다.\n버스트 탄 수는 부모·자식 합계이며 예약 예산에도 합계를 적용한다.\n바르칸 몸체에 대한 기본 명중도 현재 활성 방벽 구획으로 전달한다.\n반복 주기 예약량 검산: 32발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-VARKAN-02", BossId = "B-VARKAN", Name = "가운데 방벽의 순차 분열", Phase = 2, Telegraph = 1.5f, Bursts = 3, Count = 12, Interval = 0.9f, Speed = 12f, Damage = 15, ActiveSeconds = 2.8f, RecoverySeconds = 1.8f, Geometry = FlightStoryGeometry.SplitTriple, GeometryNotes = "방벽600→300; 활성 구획(0,4,44).\n부모3발(속도8·yaw -16/0/16°)이0.8초 뒤 각각3발로 분열한다.\n자식은 부모 고정축에 yaw -12/0/12°, pitch0°·속도12다.\n부모3+자식9=12발/버스트.\n자식 수명은 분열 시점부터 최대8초다.", SafeRoute = "방벽 전면의 낮은 사격면에서 y12~20으로 벗어나는 후보를 둔다.\n좌우 퇴로를 동시에 닫지 않으며 유효 폭4를 유지한다.\n보호 무리의 출발은 경로 위험이 사라진 뒤 허용한다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n구획 파괴는 별도 적 격파가 아니다.\n구획 경계에서 전환0.9초와 잔탄 회수를 적용한다.\n반복 주기 예약량 검산: 72발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-VARKAN-03", BossId = "B-VARKAN", Name = "마지막 방벽의 넓은 분열", Phase = 3, Telegraph = 1.5f, Bursts = 3, Count = 12, Interval = 0.9f, Speed = 12f, Damage = 20, ActiveSeconds = 2.8f, RecoverySeconds = 1.8f, Geometry = FlightStoryGeometry.SplitWide, GeometryNotes = "방벽300→0; 활성 구획(6,4,44).\n부모2발(속도8)이0.8초 뒤 각각5발로 분열한다.\n자식 yaw -24/-12/0/12/24°, pitch0°·속도12.\n부모2+자식10=12발/버스트.\n좌우 시작점(-6,4,44)/(6,4,44)에서 고정된 전방축을 사용한다.", SafeRoute = "y12~20 회피 후보를 유지하며 바르칸과 무리의 후퇴 공역을 비워 둔다.\n상하 이동과 대피 통행로의 유효 폭4를 검사한다.\n후퇴가 시작되면 추격·발사를 모두 중지한다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n바르칸의 생명력은 피해 대상에서 제외한다.\n세 구획은 한 조우이며 FINAL 보상은 안전 후퇴 확인 뒤 한 번이다.\n반복 주기 예약량 검산: 72발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-RESONANCE-01", BossId = "B-RESONANCE", Name = "중심 수정의 세 고리", Phase = 1, Telegraph = 1.5f, Bursts = 3, Count = 12, Interval = 0.7f, Speed = 12f, Damage = 15, ActiveSeconds = 1.6f, RecoverySeconds = 1.8f, Geometry = FlightStoryGeometry.Ring, GeometryNotes = "공격 저지1800→1200.\n중앙 수정(0,4,44)이 점등한 뒤 cone24°·roll30° 간격12발 고리를3회 쏜다.\n수평 중심축은 예고 때 고정하며 탄 수명8초·반경0.1이다.", SafeRoute = "z≤12의 고정 중심축 안쪽 공간을 후보로 둔다.\n반경4 이상의 안쪽 통로와 상하 진입 경로를 검사한다.\n대피선·현지 무리·작업 발판이 위험하면 이동을 멈추고 저지 구획을 분리한다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n기획11.15 중심 고리 패턴이다.\n천공수는 균열의 원인이 아니다.\n발광 결절 정밀 명중·부위 파괴 없이 몸통 기본 명중으로도 저지 가능하다.\n반복 주기 예약량 검산: 72발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-RESONANCE-02", BossId = "B-RESONANCE", Name = "좌우 발사구의 교차 직선", Phase = 2, Telegraph = 1.5f, Bursts = 4, Count = 2, Interval = 0.6f, Speed = 15f, Damage = 15, ActiveSeconds = 2f, RecoverySeconds = 1.6f, Geometry = FlightStoryGeometry.CrossLines, GeometryNotes = "공격 저지1200→600.\n좌우 발사구(-6,4,44)/(6,4,44)에서 각1발씩 쏜다.\n고정 교차점은(0,4,30)이며 네 차례 모두 같은 축을 사용한다.\n탄은 직선이고 나선·유도가 아니다.\n탄 수명8초·반경0.1.", SafeRoute = "교차 평면 y4에서 위 또는 아래로 벗어난다.\n높은 y10~18 후보를 두고 발사구 가까이 접근하지 않도록 방향 예고한다.\n빈 공역으로 이어지는 유효 폭4를 검사한다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n기획11.15의 좌우 교차 직선이다.\nFlightFinalBoss의 교차 Spiral과 구분되는 새 패턴이다.\n반복 주기 예약량 검산: 16발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
            new FlightStoryPatternProfile { Id = "BP-RESONANCE-03", BossId = "B-RESONANCE", Name = "중심 고리와 교차선의 순차 사격", Phase = 3, Telegraph = 1.5f, Bursts = 3, Count = 12, Interval = 1f, Speed = 12f, Damage = 20, ActiveSeconds = 2.2f, RecoverySeconds = 1.8f, Geometry = FlightStoryGeometry.RingCrossSequence, GeometryNotes = "공격 저지600→0.\n0초 중심12발 고리→1초 좌우 직선 각6발→2초 중심12발 고리 순서다.\n고리는 cone24°·roll30° 간격이다.\n직선6발은 각 발사구의 교차축에 yaw -10/-6/-2/2/6/10°, pitch0°다.\n모든 축은 최초 예고에 고정하며 탄 수명8초·반경0.1.", SafeRoute = "z≤12에서 고리 중심축에 가까운 x±3·y8~14 구역을 회피 후보로 둔다.\n고리 안쪽과 교차 평면 위쪽이 이어지는 유효 폭4를 검사한다.\n현재 위치에서 도달할 경로가 없으면 공격을 보류하며 안전 통과를 자동 성공시키지 않는다.", WeakPoint = "공격 종료 직후 1초 노출한다.\n약점 피해 보너스는 max(캐릭터 약점 보너스, 50%)이며 중복 가산·곱연산하지 않는다.\n몸통 기본 공격도 유효하다.", Interrupt = "단계 경계 도달 시 초과 피해를 버리고 0.9초 전환한다.\n전환 중 발사·피해·약점을 정지하고 이전 탄을 회수한다.\n저지 0이면 발사·접촉 피해를 해제하고 안전 확인을 기다린다.", Notes = "신규 장면용 초기 시험값이며 Unity 실행·플레이 검증 전이다.\n좌표는 stageAnchor의 위치+yaw를 적용한 로컬 월드 단위다.\n탄 수 예산96·전체 풀128이며 보스전 추가 적은 없다.\n한 버스트 전체 용량이 없으면 통째로 대기하고 발사 예고를 다시 한다.\n회복 시간은 첫 1초 약점 시간을 포함한다.\n한 사이클36발, 회복 포함 반복 주기5.5초의 초기값이다.\n저지0 뒤 빈 공역 이탈·추격 중지·현장 안전 확인을 받는다.\nS02만으로 최종 성공·출격 정산·특수 연구를 확정하지 않는다.\n반복 주기 예약량 검산: 72발.\n예고+공격+회복을 한 주기로30회 반복하고 탄 수명8초(분열은8.8초 예약)를 적용한 계산이다.\n이 계산은 실제 풀·물리·충돌 실행 검증이 아니다." },
        };

        public static IReadOnlyList<FlightStoryEnemyProfile> Enemies => Array.AsReadOnly(enemies);
        public static IReadOnlyList<FlightStoryPatternProfile> Patterns => Array.AsReadOnly(patterns);

        public static FlightStoryEnemyProfile FindEnemy(string id)
        {
            foreach (FlightStoryEnemyProfile profile in enemies) if (string.Equals(profile.Id, id, StringComparison.Ordinal)) return profile;
            return null;
        }

        public static IReadOnlyList<FlightStoryPatternProfile> PatternsFor(string id)
        {
            var result = new List<FlightStoryPatternProfile>();
            foreach (FlightStoryPatternProfile pattern in patterns) if (string.Equals(pattern.BossId, id, StringComparison.Ordinal)) result.Add(pattern);
            return result.AsReadOnly();
        }
    }
